package io.metersphere.agent.service;

import io.metersphere.sdk.exception.MSException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Review regressions invoke the real protocol operation entry, with explicit authorization fixtures. */
class AgentReviewRegressionTests extends AgentGovernedExecutionStateTests {
    void clock(Object target,java.time.Clock value){try{target.getClass().getDeclaredField("verificationClock");ReflectionTestUtils.setField(target,"verificationClock",value);}catch(NoSuchFieldException baselineWithoutClock){/* pre-fix comparison still exercises its wall-clock behavior */}}
    List<Map<String,Object>> refs(String id,String kind){return List.of(Map.of("kind",kind,"id",id));}
    void assertionEvidence(){
        jdbc.update("INSERT INTO agent_case_evidence(id,project_id,case_id,expires_at,sha256,content_type,size_bytes,payload,user_id,protocol_instance_id,uploader_person) VALUES ('assertion-proof','project','case',1,'assertion-hash','image/png',1,?,'assertion-author','instance','assertion-person')",new byte[]{3});
        jdbc.update("INSERT INTO msp_protocol_identity VALUES ('assertion-author','org','assertion-person',1,'fixture'),('uploader-second-account','org','uploader-person',1,'fixture')");
    }
    void taskSource(){
        jdbc.execute("ALTER TABLE ai_execution_task ADD current_execution_id VARCHAR(64)");jdbc.execute("ALTER TABLE ai_execution_task ADD status VARCHAR(32)");jdbc.update("UPDATE ai_execution_task SET current_execution_id='attempt',status='RUNNING'");
        jdbc.update("UPDATE msp_protocol_session SET source_type='TASK',source_id='task',source_execution_id='attempt'");jdbc.update("UPDATE msp_protocol_instance SET source_case_id='source-case'");
        jdbc.update("UPDATE msp_protocol_authorization SET source_type='TASK',source_id='task'");jdbc.execute("ALTER TABLE ai_execution_artifact ADD create_user VARCHAR(64)");jdbc.update("UPDATE ai_execution_artifact SET create_user='uploader'");
    }
    void finishWithOtherEvidence(){call("case.finish",Map.of("result","PASS","assertions",List.of(Map.of("assertionId","A1","observation","seen","evidence",refs("assertion-proof","PERSONAL")),Map.of("assertionId","A2","observation","seen","evidence",refs("assertion-proof","PERSONAL")))));}
    Map<String,Object> verifyRequest(){var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey",UUID.randomUUID().toString(),"sessionId","session","caseExecutionId","instance","expectedResultVersion",jdbc.queryForObject("SELECT result_version FROM msp_protocol_instance",Long.class),"submissionRevision",jdbc.queryForObject("SELECT revision FROM msp_protocol_instance",Long.class),"verificationAttemptId",UUID.randomUUID().toString()));
        var decisions=new ArrayList<Map<String,Object>>();for(String id:List.of("A1","A2")){var value=new LinkedHashMap<>(decision(id,"SATISFIED"));value.put("evidence",refs("assertion-proof","PERSONAL"));decisions.add(value);}args.put("assertions",decisions);return args;
    }
    @ParameterizedTest @CsvSource({"PERSONAL,steps","PERSONAL,stepEvidence","PERSONAL,correctedSteps","PERSONAL,actions","PERSONAL,preflightEvidence","PERSONAL,bindings","TASK,steps","TASK,stepEvidence","TASK,correctedSteps","TASK,actions","TASK,preflightEvidence","TASK,bindings","PERSONAL,preflightRecheck","TASK,preflightRecheck"})
    void nonAssertionEvidenceAuthorsAndSamePersonAccountsCannotReview(String kind,String location){
        assertionEvidence();if("TASK".equals(kind))taskSource();String id="TASK".equals(kind)?"image":"personal";var proof=refs(id,kind);
        boolean supplement=Set.of("stepEvidence","correctedSteps").contains(location);
        if(Set.of("steps","stepEvidence","correctedSteps").contains(location))call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",supplement?refs("assertion-proof","PERSONAL"):proof,"legacyAssertions",List.of()));
        else if("actions".equals(location)){var prepared=call("action.prepare",Map.of("actionType","CREATE","target","owned","expectedEffect","one","businessKey","one","queryMethod","authority"));var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey",UUID.randomUUID().toString(),"sessionId","session","caseExecutionId","instance","actionId",prepared.get("actionId"),"resolution","CONFIRMED_EFFECT","objectId","owned-object","queryEvidence","terminal authority","evidence",proof));engine.write("action.resolve",args);}
        else if("preflightRecheck".equals(location)){
            var profiles=(AgentEnvironmentProfileService)ReflectionTestUtils.getField(engine,"environments");var profile=new io.metersphere.agent.dto.AgentEnvironmentProfileDTO();profile.setVersion(1);profile.setEnvironmentId("env");org.mockito.Mockito.when(profiles.resolveForTask("profile","project")).thenReturn(profile);
            var context=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_session"));context.put("environmentProfileId","profile");context.put("environmentVersion",1);jdbc.update("UPDATE msp_protocol_session SET payload=?",store.payload(context));jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','responsible','env','GOVERN',?,1)",System.currentTimeMillis()+60000);
            updateData(data->data.put("bindings",Map.of("existing",Map.of("objectId","existing-object","conditions",Map.of(),"evidence",refs("assertion-proof","PERSONAL")))));
            for(var recheck:List.of(proof,refs("assertion-proof","PERSONAL")))call("case.prepare",Map.of("preflight",Map.of("accountId","account","environmentId","env","evidence",refs("assertion-proof","PERSONAL"),"bindings",Map.of("existing",Map.of("objectId","existing-object","conditions",Map.of(),"evidence",recheck)))));
            call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("assertion-proof","PERSONAL"),"legacyAssertions",List.of()));
        }
        else store.transaction(()->{var held=evidence.holdOwned("project","case","TASK".equals(kind)?"task":null,"instance",proof,"RESULT");updateData(data->data.put(location,"bindings".equals(location)?Map.of("existing",Map.of("objectId","actual","evidence",held)):held));return null;});
        finishWithOtherEvidence();
        if(supplement){var args=request();args.put("expectedResultVersion",1);args.put("submissionRevision",1);if("stepEvidence".equals(location))args.put("stepEvidence",List.of(Map.of("stepId","S1","evidence",proof)));else args.put("correctedSteps",List.of(Map.of("stepId","S1","observation","corrected","outcome","SATISFIED","evidence",proof)));engine.write("result.evidence.append",args);}
        for(String account:List.of("uploader","uploader-second-account")){current.set(new AgentProtocolAccess.Actor("org",account,"HUMAN","uploader-person",true));assertEquals("PROTOCOL_REVIEW_CONFLICT",assertThrows(MSException.class,()->engine.write("result.verify",verifyRequest())).getMessage());}
        assertNotEquals("ACCEPTED",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM agent_case_submission",Integer.class));
        reviewer();assertEquals(true,engine.write("result.verify",verifyRequest()).get("verificationAccepted"));
    }
    @Test void unusedUploadDoesNotVetoAnIndependentReviewer(){assertionEvidence();jdbc.update("INSERT INTO agent_case_evidence(id,project_id,case_id,expires_at,sha256,content_type,size_bytes,payload,user_id,protocol_instance_id,uploader_person) VALUES ('unused','project','case',1,'unused','image/png',1,?,'unused-author','instance','independent-person')",new byte[]{4});jdbc.update("INSERT INTO msp_protocol_identity VALUES ('unused-author','org','independent-person',1,'fixture')");store.transaction(()->evidence.hold("project","case",null,"instance",refs("unused","PERSONAL"),"RESULT"));finishWithOtherEvidence();reviewer();assertEquals(true,engine.write("result.verify",verifyRequest()).get("verificationAccepted"));}
    @Test void missingEvidenceDoesNotConsumeVerificationDeadlineAndCompleteRevisionStartsItsOwnClock(){
        var fixed=java.time.Clock.fixed(java.time.Instant.ofEpochMilli(1000),java.time.ZoneOffset.UTC);clock(results,fixed);clock(engine,fixed);
        var session=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_session"));session.put("policy",Map.of("verificationDeadlineMillis",100));jdbc.update("UPDATE msp_protocol_session SET payload=?",store.payload(session));
        submit("PASS");assertFalse(data().containsKey("pendingSince"));clock(engine,java.time.Clock.fixed(java.time.Instant.ofEpochMilli(100000),java.time.ZoneOffset.UTC));engine.expireDueResults();assertEquals("NEEDS_EVIDENCE",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));
        clock(results,java.time.Clock.fixed(java.time.Instant.ofEpochMilli(100000),java.time.ZoneOffset.UTC));var args=request();args.put("expectedResultVersion",1);args.put("submissionRevision",1);args.put("assertions",List.of(Map.of("assertionId","A2","observation","new proof","evidence",refs("personal","PERSONAL"))));engine.write("result.evidence.append",args);assertEquals(100000L,((Number)data().get("pendingSince")).longValue());engine.expireDueResults();assertEquals("PENDING",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));clock(engine,java.time.Clock.fixed(java.time.Instant.ofEpochMilli(100100),java.time.ZoneOffset.UTC));engine.expireDueResults();assertEquals("EXPIRED",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));
    }
    @Test void absentDeadlineNeverAutomaticallyExpiresPendingRevision(){submit("PASS");jdbc.update("UPDATE msp_protocol_instance SET verification='PENDING'");updateData(data->data.put("pendingSince",1));engine.expireDueResults();assertEquals("PENDING",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));}
    @Test void aReferencedEvidencePersonsIdentityCannotBeReassignedBetweenExecutionAndSubmission(){assertionEvidence();call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("personal","PERSONAL")));jdbc.update("UPDATE msp_protocol_identity SET person_ref='changed-person' WHERE user_id='uploader'");assertEquals("PROTOCOL_INDEPENDENCE_UNVERIFIABLE",assertThrows(MSException.class,this::finishWithOtherEvidence).getMessage());assertNull(jdbc.queryForObject("SELECT result FROM msp_protocol_instance",String.class));}
    @Test void unknownEvidenceAuthorIdentityCannotBeRecordedAsIndependentProof(){jdbc.update("DELETE FROM msp_protocol_identity WHERE user_id='uploader'");assertEquals("PROTOCOL_INDEPENDENCE_UNVERIFIABLE",assertThrows(MSException.class,()->call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("personal","PERSONAL")))).getMessage());assertTrue(AgentProtocolData.objects(data().get("steps")).isEmpty());}

    @Test void checkpointDoesNotExposeInternalEvidenceAuthorSnapshots(){call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("personal","PERSONAL")));String visible=AgentProtocolData.encode(engine.read("checkpoint.get",Map.of("sessionId","session","caseExecutionId","instance")));assertFalse(visible.contains("contributorPerson"));assertFalse(visible.contains("contributorUserId"));assertFalse(visible.contains("uploader-person"));}

    @Test void anExplicitlyClosedUnacceptedResultCanEndWithoutErasingItsSafetyHistory(){submit("PASS");updateData(data->{data.put("needsRevalidation",true);data.put("upstreamDisputed",true);});jdbc.update("UPDATE msp_protocol_session SET state='CLOSING'");reviewer();var args=new LinkedHashMap<String,Object>(Map.of("protocolVersion","1.0","idempotencyKey","close-unsafe-unaccepted","sessionId","session","caseExecutionId","instance","expectedResultVersion",1,"submissionRevision",1,"reason","no usable replacement","unverifiableReason","NO_AUTHORITY_QUERY"));engine.write("result.close-unaccepted",args);assertEquals("ENDED",jdbc.queryForObject("SELECT state FROM msp_protocol_session",String.class));assertEquals("UNVERIFIABLE",jdbc.queryForObject("SELECT verification FROM msp_protocol_instance",String.class));assertEquals(true,data().get("needsRevalidation"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM agent_case_submission",Integer.class));}

    @Test void anUnstartedConsumerCanExplicitlyPreflightAValidProducerWithoutImplicitRebinding(){
        var profiles=(AgentEnvironmentProfileService)ReflectionTestUtils.getField(engine,"environments");var profile=new io.metersphere.agent.dto.AgentEnvironmentProfileDTO();profile.setVersion(1);profile.setEnvironmentId("env");org.mockito.Mockito.when(profiles.resolveForTask("profile","project")).thenReturn(profile);var context=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_session"));context.put("environmentProfileId","profile");context.put("environmentVersion",1);jdbc.update("UPDATE msp_protocol_session SET payload=?",store.payload(context));jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','responsible','env','GOVERN',?,1)",System.currentTimeMillis()+60000);
        updateData(data->{var declared=AgentProtocolData.object(data.get("contract"));declared.put("dependencies",List.of(Map.of("alias","upstream","caseId","upstream-case","contractVersion",1,"bindings",Map.of())));data.put("contract",declared);data.put("needsRevalidation",true);data.put("upstreamDisputed",true);data.put("resumeTokenHash",AgentProtocolData.hash("one-use-token"));});
        jdbc.update("INSERT INTO msp_protocol_instance(id,session_id,case_id,phase,channel,verification,result,version,result_version,revision,generation,lease_owner,lease_until,calls_used,recoveries_used,recovery_ms,payload) VALUES ('explicit-producer','session','upstream-case','ENDED','CLOSED','ACCEPTED','PASS',1,2,1,1,'lease',1,0,0,0,?)",store.payload(Map.of("contract",Map.of("contractVersion",1),"syncStatus","SYNCED","outputs",Map.of())));
        assertTrue(AgentProtocolData.object(data().getOrDefault("dependencies",Map.of())).isEmpty());call("case.prepare",Map.of("preflight",Map.of("accountId","account","environmentId","env","resumeToken","one-use-token","evidence",refs("personal","PERSONAL")),"dependencyInstances",Map.of("upstream",Map.of("instanceId","explicit-producer","resultVersion",2))));
        assertEquals(false,data().get("needsRevalidation"));assertEquals(false,data().get("upstreamDisputed"));assertEquals("explicit-producer",AgentProtocolData.object(AgentProtocolData.object(data().get("dependencies")).get("upstream")).get("instanceId"));assertTrue(AgentProtocolData.objects(data().get("actions")).isEmpty());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM effects",Integer.class));
    }

    @Test void aPreFixRecoveryEvidenceAuthorIsReconstructedFromSuccessfulAuditBeforeReview(){
        assertionEvidence();var failure=call("step.save",Map.of("stepId","S1","observation","failed","outcome","UNKNOWN","evidence",refs("assertion-proof","PERSONAL")));var permit=call("recovery.record",Map.of("failureEventId",failure.get("eventId"),"observation","new proof","changedCondition","service recovered","proposedAction","retry after verified fix","expectedObservation","visible","evidence",refs("personal","PERSONAL")));call("step.save",Map.of("stepId","S1","observation","now visible","outcome","SATISFIED","recoveryPermitId",permit.get("recoveryPermitId"),"evidence",refs("assertion-proof","PERSONAL")));
        updateData(data->{var identities=AgentProtocolData.object(data.getOrDefault("evidenceIdentities",Map.of()));identities.remove("uploader");data.put("evidenceIdentities",identities);var persons=new ArrayList<>(AgentProtocolData.strings(data.getOrDefault("evidencePersons",List.of())));persons.remove("uploader-person");data.put("evidencePersons",persons);});finishWithOtherEvidence();current.set(new AgentProtocolAccess.Actor("org","uploader-second-account","HUMAN","uploader-person",true));assertEquals("PROTOCOL_REVIEW_CONFLICT",assertThrows(MSException.class,()->engine.write("result.verify",verifyRequest())).getMessage());reviewer();assertEquals(true,engine.write("result.verify",verifyRequest()).get("verificationAccepted"));
    }
    @Test void unusedExtraPreflightBindingAndItsUploadDoNotVetoReview(){
        assertionEvidence();var profiles=(AgentEnvironmentProfileService)ReflectionTestUtils.getField(engine,"environments");var profile=new io.metersphere.agent.dto.AgentEnvironmentProfileDTO();profile.setVersion(1);profile.setEnvironmentId("env");org.mockito.Mockito.when(profiles.resolveForTask("profile","project")).thenReturn(profile);var context=store.data(jdbc.queryForMap("SELECT * FROM msp_protocol_session"));context.put("environmentProfileId","profile");context.put("environmentVersion",1);jdbc.update("UPDATE msp_protocol_session SET payload=?",store.payload(context));jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','responsible','env','GOVERN',?,1)",System.currentTimeMillis()+60000);
        call("case.prepare",Map.of("preflight",Map.of("accountId","account","environmentId","env","evidence",refs("assertion-proof","PERSONAL"),"bindings",Map.of("not-an-existing-binding",Map.of("objectId","unused","evidence",refs("personal","PERSONAL"))))));call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("assertion-proof","PERSONAL")));finishWithOtherEvidence();current.set(new AgentProtocolAccess.Actor("org","uploader-second-account","HUMAN","uploader-person",true));assertEquals(true,engine.write("result.verify",verifyRequest()).get("verificationAccepted"));
    }
    @Test void aRejectedReferenceDoesNotLeakItsAuthorCaptureIntoTheNextRequest(){
        assertionEvidence();assertThrows(MSException.class,()->call("step.save",Map.of("stepId","S1","observation","rejected variable","outcome","SATISFIED","evidence",refs("personal","PERSONAL"),"variables",Map.of("undeclared",1))));assertTrue(AgentProtocolData.objects(data().get("steps")).isEmpty());call("step.save",Map.of("stepId","S1","observation","observed","outcome","SATISFIED","evidence",refs("assertion-proof","PERSONAL")));finishWithOtherEvidence();current.set(new AgentProtocolAccess.Actor("org","uploader-second-account","HUMAN","uploader-person",true));assertEquals(true,engine.write("result.verify",verifyRequest()).get("verificationAccepted"));
    }

}
